import React from 'react';
import { render, screen } from '@testing-library/react';
import Portal from './Portal';

const containerEl = document.createElement('div');
containerEl.setAttribute('data-testid', 'container-el');
document.body.appendChild(containerEl);

describe('Portal', () => {
  test('should render an element inside the mount node', () => {
    render(
      <Portal container={document.querySelector('[data-testid="container-el"]')}>
        <div>Test node</div>
      </Portal>
    );

    expect(screen.getByTestId('container-el')).toBeInTheDocument();
    const mountNode = screen.getByTestId('container-el');
    expect(mountNode.childNodes[0]).toHaveTextContent('Test node');
  });

  test('should render an element inside the document body if mount node is undefined', () => {
    render(
      <Portal container={document.querySelector('[data-testid="not-existent-node"]')}>
        <div>Test node</div>
      </Portal>
    );

    expect(screen.queryByTestId('not-existent-node')).not.toBeInTheDocument();
    const mountNode = screen.queryByTestId('not-existent-node');
    expect(mountNode).not.toBeInTheDocument();
    expect(screen.getByText('Test node')).toBeInTheDocument();
  });

  test('should render an element inside the document body if mount node is invalid React element', () => {
    render(
      <Portal container={{ test: 'test' } as unknown as Element}>
        <div>Test node</div>
      </Portal>
    );

    expect(screen.queryByTestId('not-existent-node')).not.toBeInTheDocument();
    const mountNode = screen.queryByTestId('not-existent-node');
    expect(mountNode).not.toBeInTheDocument();
    expect(screen.getByText('Test node')).toBeInTheDocument();
  });
});
